inpatient_record = frappe.form_dict.get("inpatient_record")

if not inpatient_record:
    frappe.response["message"] = []

else:

    ip = frappe.get_doc("Inpatient Record", inpatient_record)

    items = []

    for row in ip.drug_prescription:

        if not row.drug_code:
            continue

        # -------------------------
        # Item Name
        # -------------------------
        item_name = (
            frappe.db.get_value("Item", row.drug_code, "item_name")
            or row.drug_name
            or row.drug_code
        )

        # -------------------------
        # Selling Price
        # -------------------------
        rate = (
            frappe.db.get_value(
                "Item Price",
                {
                    "item_code": row.drug_code,
                    "selling": 1
                },
                "price_list_rate"
            )
            or 0
        )

        # -------------------------
        # Calculate Daily Dose
        # -------------------------
        daily_dose = 1

        if row.dosage:

            dosage = row.dosage.strip()

            if dosage == "1-0-0":
                daily_dose = 1

            elif dosage == "0-1-0":
                daily_dose = 1

            elif dosage == "0-0-1":
                daily_dose = 1

            elif dosage == "1-0-1":
                daily_dose = 2

            elif dosage == "1-1-1":
                daily_dose = 3

            elif dosage == "1-1-1-1":
                daily_dose = 4

            elif dosage == "BID":
                daily_dose = 2

            elif dosage == "TID":
                daily_dose = 3

            elif dosage == "QID":
                daily_dose = 4

            elif dosage == "5 times a day":
                daily_dose = 5

        # -------------------------
        # Calculate Duration
        # -------------------------
        days = 1

        if row.period:

            parts = row.period.split(" ")

            if len(parts) >= 2:

                try:
                    value = int(parts[0])
                except:
                    value = 1

                unit = parts[1]

                if unit == "Day":
                    days = value

                elif unit == "Week":
                    days = value * 7

                elif unit == "Hour":
                    days = 1

        qty = daily_dose * days

        items.append({
            "item_code": row.drug_code,
            "item_name": item_name,
            "drug_name": row.drug_name,
            "dosage": row.dosage,
            "period": row.period,
            "qty": qty,
            "rate": rate
        })

    frappe.response["message"] = items

def to_title_case(text):
    if not text:
        return text

    return " ".join(word.capitalize() for word in text.split())

doc.first_name = to_title_case(doc.first_name)
doc.last_name = to_title_case(doc.last_name)
